/**
 * Generated by scaffold-fixtures-per-entity. Inserts a Category row
 * directly via the repository. Useful for tests that need a pre-seeded record
 * without going through the full HTTP create flow.
 */
import { DataSource } from 'typeorm';

export interface CreateCategoryInput {
  [key: string]: unknown;
}

export async function createTestCategory(
  dataSource: DataSource,
  overrides: CreateCategoryInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'Category' || m.tableName === 'categories',
  );
  if (!meta) {
    throw new Error('createTestCategory: Category entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    name: 'test-name',
    slug: 'test-slug',
    iconUrl: 'test-iconUrl',
    description: 'test-description',
    displayOrder: 0,
    isActive: false,
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
